<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Holder\UserProfilePictureUrlAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfilePictureUrlAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserProfilePictureUrlAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getPictureUrl returns null on a freshly created holder.
     */
    public function testPictureUrlNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserProfilePictureUrlAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isPictureUrlAssigned());
        $this->assertNull($holder->getPictureUrl());
    }
}
class ImplWithUserProfilePictureUrlAttributeHolderUnitTest
{
    use UserProfilePictureUrlAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedPictureUrlRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultPictureUrl();
    }
}
